ick.com"><div class="dropdown-topic svelte-1wxfnil">Trung tâm kiến thức</div></a> <a href="../../../support/faqs/index.htm"><div class="dropdown-topic svelte-1wxfnil">FAQs</div></a></div></div> <div class="nav-cat-subnav-topic svelte-1wxfnil"><span class="topic-title svelte-1wxfnil">Công ty</span> <div class="topic-content svelte-1wxfnil"><a href="../../../company/about-us/index.htm"><div class="dropdown-topic svelte-1wxfnil">Về chúng tôi</div></a> <a href="../../../company/careers/index.htm"><div class="dropdown-topic svelte-1wxfnil">Tuyển dụng</div></a> <a href="../../../enterprise/index.htm"><div class="dropdown-topic svelte-1wxfnil">Enterprise</div></a></div></div> <div class="nav-cat-subnav-topic svelte-1wxfnil"><span class="topic-title svelte-1wxfnil">Blog</span> <div class="topic-content svelte-1wxfnil"><a href="../index.htm"><div class="dropdown-topic svelte-1wxfnil">Tin tức</div></a></div></div></div></div> <div class="menu-topic"><div class="nav-cat industries svelte-1wxfnil ">Ngành nghề <span class="material-symbols-outlined svelte-1wxfnil ">keyboard_arrow_down</span></div> <div class="nav-cat-subnav svelte-1wxfnil "><div class="nav-cat-subnav-topic svelte-1wxfnil"><div class="topic-content svelte-1wxfnil"><a href="../../../industries/agriculture/index.htm"><div class="dropdown-topic svelte-1wxfnil">Nông nghiệp</div></a> <a href="../../../industries/healthcare/index.htm"><div class="dropdown-topic svelte-1wxfnil">Chăm sóc sức khỏe</div></a> <a href="../../../industries/field-service/index.htm"><div class="dropdown-topic svelte-1wxfnil">Dịch vụ hiện trường</div></a></div></div></div></div> <div class="nav-cat svelte-1wxfnil"><a href="../../../trial-program/index.htm">Chương trình thử nghiệm</a></div> <div class="nav-cat svelte-1wxfnil"><a href="../../../pricing/index.htm">Bảng giá</a></div> <div class="nav-cat svelte-1wxfnil"><a href="https://shop.iristick.com/products" target="_blank" data-umami-event="shop_mobile_nav_link">Cửa hàng</a></div></div></nav></div><!----> <!----><div><!----><!----> <!----> <!----> <div class="app-container"><div class="componentblock newsblock svelte-tc7a4d"><span class="breadcrumb svelte-tc7a4d"><a href="../index.htm" class="svelte-tc7a4d">Tin tức</a> / Tham gia với chúng tôi webinar đồng chủ sở hữu với Handtmann và Icona</span> <img src="../../../_app/immutable/assets/Handtmann_Acty_Webinar.V0XF82a4.webp" alt="giới thiệu" class="svelte-tc7a4d"> <h1 class="svelte-tc7a4d">Hãy tham gia cùng chúng tôi với Handtmann và Icona</h1> <p class="bold intro svelte-tc7a4d">Hãy tham gia cùng chúng tôi vào ban tham mưu vào thứ tư, 21 tháng 9, cộng tác với Iristick, Handtmann và Icona. Chúng tôi sẽ chứng minh rằng công nghệ kính thông minh, kết hợp với phần mềm đúng đắn, có thể nâng cao hiệu quả và giảm chi phí trong kinh doanh của bạn. Đăng ký bây giờ để tìm hiểu làm thế nào giải pháp của chúng tôi có thể cho phép các đào tạo nhanh hơn và hiệu quả hơn, và giúp giảm thiểu hiệu quả của sự thiếu hụt lao động trong ngành công nghiệp sản xuất.</p> <!--[--><div class="block"><!--[!--><!--]--> <!--[!--><!--]--> <!---->Trong suốt cuộc chiến, <span class='bold'>Katrina Auskapa, Bộ quản lý bán hàng, Icona</span>sẽ đưa ra một bản tóm tắt về phần mềm trợ giúp từ xa cho phép đào tạo từ xa và hợp tác ảo.<!----> <!--[!--><!--]--></div><div class="block"><!--[!--><!--]--> <!--[!--><!--]--> <!---->Bài thuyết trình của cô sẽ được theo sau bởi <span class='bold'>Jacob Kent, thủ lĩnh Bắc Mỹ tại Iristick </span> người sẽ nói về việc làm thế nào mà chiếc kính thông minh Iristick có thể giúp giảm đáng kể thời gian để đào tạo một nhân viên mới, mà có thể rất quan trọng cho các công ty ngày nay với sự thiếu hụt lao động toàn cầu mà chúng ta đang trải qua.<!----> <!--[!--><!--]--></div><div class="block"><!--[!--><!--]--> <!--[!--><!--]--> <!---->Cuối cùng, <span class='bold'>Shawn Kentch, Huấn luyện viên, Handtmann</span>sẽ chia sẻ trường hợp sử dụng của họ và giới thiệu về HVision: một dịch vụ được tạo ra đặc biệt cho khách hàng của họ bao gồm cả chiếc kính thông minh Acty của Clone App và ZXQ14QZ.<!----> <!--[!--><!--]--></div><div class="block"><!--[!--><!--]--> <!--[!--><!--]--> <!---->Chúng tôi sẽ kết thúc với một đề nghị đặc biệt và thông báo từ Icona và một phiên họp Q&amp;A.<!----> <!--[!--><!--]--></div><!--]--> <div class="acknowledgements svelte-tc7a4d"><span>Sybren Hamers</span> <span>6 Tháng 9 năm 2022</span></div></div></div><!----><!----></div><!----> <!--[!--><!--]--><!----> <div class="footer-wrapper svelte-19h1qln"><footer class="svelte-19h1qln"><div class="upper-footer svelte-19h1qln"><div class="footer_company svelte-19h1qln"><span class="footer-title svelte-19h1qln">Liên hệ với chúng tôi!</span> <p class="mail animate svelte-19h1qln"><a class="link svelte-19h1qln" href="mailto:contact@iristick.vn">contact@iristick.vn</a><span class="material-symbols-outlined">mail</span></p> <br> <span>Lamorinisterstraat 123, box 102 Be- 2018 Antwerp (Belgium)</span> <span>(+32) (0)3 435 65 60</span> <br> <span>Theo dõi chúng tôi trên <a class="link svelte-19h1qln" target="_blank" href="https://www.linkedin.com/company/iristick">LinkedIn</a>.</span></div> <div class="footer_container svelte-19h1qln"><div class="footer_group svelte-19h1qln"><p class="svelte-19h1qln">Sản phẩm</p> <a href="../../../products/Iristick.Collector/index.htm" class="svelte-19h1qln">Iristick.Collector</a> <a href="../../../products/Iristick.Teams/index.htm" class="svelte-19h1qln">Iristick.Teams</a> <a href="../../../products/Iristick.Assist/index.htm" class="svelte-19h1qln">Iristick.Assist</a> <a href="../../../developers/index.htm" data-umami-event="footer_sdk" class="svelte-19h1qln">Iristick.SDK</a></div> <div class="footer_group svelte-19h1qln"><p class="svelte-19h1qln">Phần cứng</p> <a href="../../../index.htm" class="svelte-19h1qln">Iristick.G3</a> <a href="../../../tools/Iristick.G2-PRO/index.htm" class="svelte-19h1qln">Iristick.G2</a> <a href="../../../tools/Iristick.H1/index.htm" class="svelte-19h1ql